defmodule JoobQ.Worker.GatewayTest do
  use ExUnit.Case, async: true

  alias JoobQ.Config
  alias JoobQ.Worker.Gateway

  defp config do
    opts = [queues: ["mail"], worker_id: "w-1", team: "core"]
    Config.new!([url: "https://x", token: "t"] ++ opts)
  end

  test "the registration names the worker, its language, version, queues and concurrency" do
    body = Gateway.register_body(config(), 3)

    assert %{
             "worker_id" => "w-1",
             "sdk_language" => "elixir",
             "task_queues" => ["mail"],
             "concurrency" => 4,
             "active_leases" => 3,
             "team" => "core",
             "service_name" => nil,
             "delivery_mode" => "poll"
           } = body

    assert body["sdk_version"] == JoobQ.sdk_version()
    assert is_integer(body["pid"]) and is_binary(body["host"])
    refute inspect(body) =~ "token"
  end

  test "backs off from 250 ms, doubling to 5 s, and starts again after a success" do
    assert Enum.scan(1..6, nil, fn _, previous -> Gateway.backoff(previous) end) ==
             [250, 500, 1_000, 2_000, 4_000, 5_000]

    assert Gateway.retry_after({:error, :down}, 500, 10_000) == {1_000, 1_000}
    assert Gateway.retry_after({:ok, %{}}, 500, 10_000) == {10_000, nil}
  end

  test "a poll's answer gives at most the tasks asked for, and one without a list is an error" do
    tasks = for n <- 1..10, do: %{"lease_token" => "l#{n}"}
    assert {:ok, three} = Gateway.tasks(%{"tasks" => [%{"id" => "no token"} | tasks]}, 3)
    assert Enum.map(three, & &1["lease_token"]) == ["l1", "l2", "l3"]
    assert Gateway.tasks(%{}, 3) == :error
    assert Gateway.tasks(%{"tasks" => "x"}, 3) == :error
  end

  test "a worker call may take the poll's wait and a sixth of a lease" do
    assert Gateway.timeout(config()) == 10_000
  end
end
